
import type { Promotion } from './Promotion.js';

export type PromotionCode = { "code": string; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "expires_at"?: string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "max_uses"?: string; "merchant_id"?: string; "metadata"?: Record<string, string>; /** The promotion this code belongs to. Present only when the list request asked for expand=promotion. */ "promotion"?: Promotion; "promotion_code_id": string; "promotion_id": string; /** Read-only, computed from stored active or inactive state, expires_at, and max_uses: active, inactive, expired, or exhausted. Only active and inactive can be set via PATCH. */ "status": "active" | "inactive" | "expired" | "exhausted" | (string & {}); "timezone"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "uses_count": string; };
